func (h *EntryHeap) Push(x interface{}) { *h = append(*h, x.(Entry)) }
func (h *EntryHeap) Pop() interface{} {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

lists := [][]int{{1, 4, 7}, {2, 5}, {0, 6, 9}}
merged := []int{}
{{code}}
fmt.Println(merged)
```

```go
h := &EntryHeap{}
for i, list := range lists {
	if len(list) > 0 {
		heap.Push(h, Entry{list[0], i, 0})
	}
}
for h.Len() > 0 {
	e := heap.Pop(h).(Entry)
	merged = append(merged, e.Value)
	if next := e.Index + 1; next < len(lists[e.List]) {
		heap.Push(h, Entry{lists[e.List][next], e.List, next})
	}
