func main() {
	low, high := &MaxHeap{}, &MinHeap{}
	for count := 1; ; count++ {
		var x int
		if _, err := fmt.Scan(&x); err != nil {
			break
		}
		heap.Push(low, x)
		heap.Push(high, heap.Pop(low))
		if high.Len() > low.Len() {
			heap.Push(low, heap.Pop(high))
		}
		median := float64((*low)[0])
		if low.Len() == high.Len() {
			median = float64((*low)[0]+(*high)[0]) / 2
		}
		fmt.Printf("after %d: %.1f\n", count, median)
	}
}

